
(function () {
  // Atsauksmju pārbaudes noteikumi
  const namePattern = /^[\p{L}\p{M}][\p{L}\p{M} .\u2019'-]*$/u;
  const emailPattern = /^[^\s@<>]+@[^\s@<>.]+(?:\.[^\s@<>.]+)+$/u;

  function cleanText(value) {
  if (typeof value === "string") {
    // trim() noņem atstarpes teksta sākumā un beigās.
    return value.trim();
  }

  return "";
  }

  // Galerija
  const slides = Array.from(document.querySelectorAll(".gallery__slide"));
  const galleryStatus = document.querySelector("#gallery-status");
  const previousButton = document.querySelector("#previous-slide");
  const nextButton = document.querySelector("#next-slide");

  let currentSlide = 0;

  function showSlide(index) {
    slides[currentSlide].hidden = true;

    currentSlide = (index + slides.length) % slides.length;

    const slide = slides[currentSlide];
    slide.hidden = false;

    const title = slide.querySelector("h3").textContent;

    galleryStatus.textContent =
      `${currentSlide + 1} / ${slides.length} · ${title}`;
  }

  previousButton.addEventListener("click", function () {
    showSlide(currentSlide - 1);
  });

  nextButton.addEventListener("click", function () {
    showSlide(currentSlide + 1);
  });

  showSlide(0);


  // Budžeta kalkulators
  const budgetForm = document.querySelector("#budget-form");
  const daysInput = document.querySelector("#days");
  const dailyCostInput = document.querySelector("#daily-cost");
  const budgetTotal = document.querySelector("#budget-total");

  const currencyFormatter = new Intl.NumberFormat("lv-LV", {
    style: "currency",
    currency: "EUR"
  });

  function calculateBudget() {
    if (!daysInput.validity.valid) {
      budgetTotal.value =
        `Ievadi veselu dienu skaitu no ${daysInput.min} līdz ${daysInput.max}.`;
      return;
    }

    if (!dailyCostInput.validity.valid) {
      budgetTotal.value =
        `Ievadi summu no ${dailyCostInput.min} līdz ${dailyCostInput.max} EUR ar ne vairāk kā divām zīmēm aiz komata.`;
      return;
    }

    const days = daysInput.valueAsNumber;
    const dailyCost = Math.round(dailyCostInput.valueAsNumber * 100) / 100;
    const total = days * dailyCost;

    budgetTotal.value = `Kopā: ${currencyFormatter.format(total)}`;
  }

  budgetForm.addEventListener("input", calculateBudget);

  budgetForm.addEventListener("submit", function (event) {
    event.preventDefault();
  });

  calculateBudget();


  // Atsauksmju forma
  const feedbackForm = document.querySelector("#feedback-form");
  const feedbackStatus = document.querySelector("#feedback-status");
  const submitButton = feedbackForm.querySelector("button");
  const feedbackFields = feedbackForm.querySelectorAll("[name]");

  feedbackForm.noValidate = true;

  // Kļūdu attēlošana
  function showFeedbackErrors(errors) {
    let firstInvalidField = null;

    for (const field of feedbackFields) {
      const errorMessage = errors[field.name];
      const errorId = field.getAttribute("aria-describedby");
      const errorElement = document.getElementById(errorId);

      if (errorMessage) {
        errorElement.textContent = errorMessage;
        errorElement.hidden = false;
        field.setAttribute("aria-invalid", "true");

        if (firstInvalidField === null) {
          firstInvalidField = field;
        }
      } else {
        errorElement.textContent = "";
        errorElement.hidden = true;
        field.removeAttribute("aria-invalid");
      }
    }

    if (firstInvalidField !== null) {
      firstInvalidField.focus();
      return true;
    }

    return false;
  }

  // Ievadīto datu pārbaude
  function validateFeedback(data) {
    const errors = {};

    const name = cleanText(data.name);
    const email = cleanText(data.email);
    const message = cleanText(data.message);

    if (name === "") {
      errors.name = "Ievadi vārdu.";
    } else if (name.length > 80) {
      errors.name = "Vārdā drīkst būt līdz 80 rakstzīmēm.";
    } else if (!namePattern.test(name)) {
      errors.name = "Ievadi vārdu ar burtiem.";
    }

    if (email === "") {
      errors.email = "Ievadi e-pasta adresi.";
    } else if (email.length > 254 || !emailPattern.test(email)) {
      errors.email = "Ievadi derīgu e-pasta adresi.";
    }

    if (message === "") {
      errors.message = "Ievadi atsauksmi.";
    } else if (message.length > 500) {
      errors.message = "Atsauksmē drīkst būt līdz 500 rakstzīmēm.";
    }

    return errors;
  }

  // Atsauksmes nosūtīšana
  // async ļauj funkcijā izmantot await, neapturot pārējās lapas darbību.
  feedbackForm.addEventListener("submit", async function (event) {
    event.preventDefault();

    if (submitButton.disabled) {
      return;
    }

    feedbackStatus.textContent = "";

    const formData = new FormData(feedbackForm);
    const data = Object.fromEntries(formData);
    const errors = validateFeedback(data);

    if (showFeedbackErrors(errors)) {
      return;
    }

    submitButton.disabled = true;
    feedbackStatus.textContent = "Nosūta atsauksmi…";

    try {
        // await sagaida servera atbildi, nebloķējot pārlūka darbību.
      const response = await fetch(feedbackForm.action, {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify(data)
      });
        // await sagaida atbildes JSON datu nolasīšanu.
      const result = await response.json();

      if (response.ok) {
        feedbackForm.reset();
      } else {
        if (result.errors) {
          showFeedbackErrors(result.errors);
        }
      }

      feedbackStatus.textContent = result.message;
    } catch (error) {
      feedbackStatus.textContent =
        "Neizdevās sazināties ar serveri. Mēģini vēlreiz.";
    } finally {
      submitButton.disabled = false;
    }
  });
})();
